/*
 * Site-wide search (search.html only). Dependency-free.
 *
 * Reads window.SEARCH_INDEX (js/search-index.js, generated by tools/build_site.py) and
 * matches every word of the query against each entry's title, subtitle, "where it lives" line
 * and full text. Accents, curly quotes and case are ignored. Results are ranked: a match in
 * the title beats the subtitle, which beats the meta line, which beats the body.
 *
 * Result text is always set with textContent / text nodes, never innerHTML, so nothing in the
 * index can inject markup. The query lives in the address (?q=...&type=s), so a search can be
 * bookmarked or shared.
 */
(function () {
  "use strict";

  var app = document.getElementById("search-app");
  if (!app) return;

  var input = app.querySelector("#s-q");
  var chipRow = app.querySelector(".chips");
  var chips = app.querySelectorAll(".chip");
  var status = app.querySelector(".search-status");
  var list = app.querySelector(".search-results");
  var moreBtn = app.querySelector(".search-more");

  var PAGE = 30;
  var KIND_NAME = { c: "Case", s: "Subject", r: "Record", a: "Archive" };
  var KIND_WEIGHT = { c: 4, s: 3, a: 3, r: 1 };
  var IDLE = status.textContent;

  var docs = window.SEARCH_INDEX;
  if (!docs || !docs.length) {
    status.textContent = "The search index could not be loaded. Try reloading the page.";
    return;
  }

  /* Length-preserving normalisation, so a position found in the normalised text is the same
     position in the original (needed to cut snippets and highlight matches). Each accented
     letter maps to its single base letter; curly quotes become straight ones. */
  function norm(s) {
    return s.toLowerCase()
      .replace(/[À-ɏ]/g, function (ch) { return ch.normalize("NFD").charAt(0); })
      .replace(/[‘’ʼ]/g, "'")
      .replace(/[“”]/g, '"');
  }

  docs.forEach(function (d) {
    d.nt = norm(d.t);
    d.nd = d.d ? norm(d.d) : "";
    d.nm = norm(d.m);
    d.nx = norm(d.x);
  });

  function wordStart(hay, tok) { return (" " + hay).indexOf(" " + tok) > -1; }

  /* How well one word matches one entry: title beats subtitle beats the "where it lives"
     line beats the body. 0 means the word is nowhere in the entry. */
  function wordScore(d, t) {
    var s = 0;
    if (d.nt.indexOf(t) > -1) s += wordStart(d.nt, t) ? 30 : 15;
    if (d.nd && d.nd.indexOf(t) > -1) s += 8;
    if (d.nm.indexOf(t) > -1) s += 6;
    var at = d.nx.indexOf(t);
    if (at > -1) {
      s += 2;
      if (d.nx.indexOf(t, at + t.length) > -1) s += 1;
    }
    return s;
  }

  /* Entry score from its per-word scores `row`, each word weighted by how rare it is across
   * the archive (so "osric" counts for more than "king"). Strict: every word must match, else
   * 0. Partial: words that match nothing are skipped. */
  function score(d, row, weights, toks, phrase, partial) {
    var total = 0, matched = 0;
    for (var i = 0; i < row.length; i++) {
      if (!row[i]) {
        if (partial) continue;
        return 0;
      }
      matched++;
      total += row[i] * weights[i];
    }
    if (!matched) return 0;
    if (d.nt === phrase) total += 60;
    else if (d.nt.indexOf(phrase) === 0) total += 25;
    else if (toks.length > 1 && d.nx.indexOf(phrase) > -1) total += 10;
    return total + (KIND_WEIGHT[d.k] || 0);
  }

  /* Ranges of `norm` text covered by any query word, merged. */
  function ranges(nhay, toks) {
    var out = [];
    toks.forEach(function (t) {
      var i = nhay.indexOf(t);
      var guard = 0;
      while (i > -1 && guard++ < 50) {
        out.push([i, i + t.length]);
        i = nhay.indexOf(t, i + t.length);
      }
    });
    out.sort(function (a, b) { return a[0] - b[0]; });
    var merged = [];
    out.forEach(function (r) {
      var last = merged[merged.length - 1];
      if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]); else merged.push(r.slice());
    });
    return merged;
  }

  /* Append `text` to `el`, wrapping the parts that match the query words in <mark>. */
  function highlight(el, text, ntext, toks) {
    var rs = ranges(ntext, toks), pos = 0;
    rs.forEach(function (r) {
      if (r[0] > pos) el.appendChild(document.createTextNode(text.slice(pos, r[0])));
      var m = document.createElement("mark");
      m.textContent = text.slice(r[0], r[1]);
      el.appendChild(m);
      pos = r[1];
    });
    if (pos < text.length) el.appendChild(document.createTextNode(text.slice(pos)));
  }

  /* About 170 characters of the body around the first match, cut at word edges. */
  function snippet(d, toks) {
    var first = -1;
    toks.forEach(function (t) {
      var i = d.nx.indexOf(t);
      if (i > -1 && (first < 0 || i < first)) first = i;
    });
    if (first < 0) return null;              // matched only in title/meta: no body snippet
    var from = Math.max(0, first - 60), to = Math.min(d.x.length, first + 110);
    if (from > 0) { var sp = d.x.indexOf(" ", from); if (sp > -1 && sp < first) from = sp + 1; }
    if (to < d.x.length) { var sp2 = d.x.lastIndexOf(" ", to); if (sp2 > first) to = sp2; }
    return { text: (from > 0 ? "…" : "") + d.x.slice(from, to) + (to < d.x.length ? "…" : ""),
             off: from, lead: from > 0 ? 1 : 0 };
  }

  function item(d, toks) {
    var li = document.createElement("li");
    li.className = "search-hit";
    var a = document.createElement("a");
    a.href = d.u;
    if (d.i) {
      var img = document.createElement("img");
      img.src = d.i; img.alt = ""; img.loading = "lazy";
      a.appendChild(img);
    }
    var box = document.createElement("span");
    box.className = "hit-body";

    var kind = document.createElement("span");
    kind.className = "hit-kind";
    kind.textContent = KIND_NAME[d.k];
    box.appendChild(kind);

    var title = document.createElement("span");
    title.className = "hit-title";
    highlight(title, d.t, d.nt, toks);
    box.appendChild(title);

    var meta = document.createElement("span");
    meta.className = "hit-meta";
    meta.textContent = d.m;
    box.appendChild(meta);

    var sn = snippet(d, toks);
    if (sn) {
      var p = document.createElement("span");
      p.className = "hit-snippet";
      // Highlight inside the snippet using the matching slice of the normalised text.
      var body = sn.text, nbody = norm(body);
      highlight(p, body, nbody, toks);
      box.appendChild(p);
    } else if (d.d) {
      var sub = document.createElement("span");
      sub.className = "hit-snippet";
      highlight(sub, d.d, d.nd, toks);
      box.appendChild(sub);
    }
    a.appendChild(box);
    li.appendChild(a);
    return li;
  }

  var state = { q: "", kind: "", shown: PAGE, hits: [], all: [], exact: 0 };

  function tokens(q) { return norm(q).split(/\s+/).filter(Boolean); }

  function compute() {
    var toks = tokens(state.q);
    if (!toks.length) { state.hits = []; state.all = []; state.exact = 0; return toks; }
    var phrase = toks.join(" ");
    var byScore = function (a, b) { return b.s - a.s || (a.d.t < b.d.t ? -1 : a.d.t > b.d.t ? 1 : 0); };
    var rows = new Array(docs.length), df = toks.map(function () { return 0; }), i, j;
    for (i = 0; i < docs.length; i++) {
      rows[i] = toks.map(function (t, k) { var w = wordScore(docs[i], t); if (w) df[k]++; return w; });
    }
    var weights = df.map(function (c) { return Math.log(1 + docs.length / Math.max(c, 1)); });
    var exact = [], extra = [];
    for (i = 0; i < docs.length; i++) {
      var s = score(docs[i], rows[i], weights, toks, phrase, false);
      if (s) { exact.push({ d: docs[i], s: s }); continue; }
      if (toks.length > 1) {
        var ps = score(docs[i], rows[i], weights, toks, phrase, true);
        if (ps) extra.push({ d: docs[i], s: ps });
      }
    }
    exact.sort(byScore);
    state.exact = exact.length;
    // Few entries contain every word: after them, list the best entries that contain some of
    // the words (a search for "king osric" should still find Osric). Capped so one common word
    // cannot flood the list.
    var all = exact;
    if (exact.length < 5 && extra.length) {
      extra.sort(byScore);
      all = exact.concat(extra.slice(0, 40));
    }
    state.all = all;
    state.hits = state.kind ? all.filter(function (h) { return h.d.k === state.kind; }) : all;
    return toks;
  }

  function render(toks) {
    list.textContent = "";
    var q = state.q.trim();
    if (!toks.length) {
      chipRow.hidden = true;
      moreBtn.hidden = true;
      status.textContent = IDLE;
      return;
    }
    chipRow.hidden = false;
    // Chip counts come from all matches, so the other types stay visible while one is selected.
    var counts = { "": state.all.length, c: 0, s: 0, r: 0, a: 0 };
    state.all.forEach(function (h) { counts[h.d.k]++; });
    chips.forEach(function (c) {
      var k = c.dataset.kind;
      if (!c.dataset.label) c.dataset.label = c.textContent;
      c.textContent = c.dataset.label + " (" + counts[k] + ")";
      c.disabled = k !== "" && counts[k] === 0 && state.kind !== k;
      var on = k === state.kind;
      c.classList.toggle("is-on", on);
      c.setAttribute("aria-pressed", String(on));
    });
    var n = state.hits.length;
    if (!n) {
      status.textContent = "No results for “" + q + "”. Try fewer words, or a different spelling.";
      moreBtn.hidden = true;
      return;
    }
    var head = n + (n === 1 ? " result for “" : " results for “") + q + "”";
    if (state.exact < state.all.length) {
      head = state.exact
        ? state.exact + (state.exact === 1 ? " entry contains" : " entries contain") + " every word of “" + q + "”; the rest match only some of them."
        : "Nothing contains every word of “" + q + "”. Showing entries that match some of them.";
    }
    status.textContent = head;
    var frag = document.createDocumentFragment();
    state.hits.slice(0, state.shown).forEach(function (h) { frag.appendChild(item(h.d, toks)); });
    list.appendChild(frag);
    var left = n - state.shown;
    moreBtn.hidden = left <= 0;
    if (left > 0) moreBtn.textContent = "Show " + Math.min(PAGE, left) + " more (" + left + " left)";
  }

  function syncUrl() {
    if (!window.history || !history.replaceState) return;
    var qs = [];
    if (state.q.trim()) qs.push("q=" + encodeURIComponent(state.q.trim()));
    if (state.kind) qs.push("type=" + state.kind);
    try { history.replaceState(null, "", location.pathname + (qs.length ? "?" + qs.join("&") : "")); } catch (e) { /* file:// or sandbox: ignore */ }
  }

  function run(resetPaging) {
    if (resetPaging) state.shown = PAGE;
    render(compute());
    syncUrl();
  }

  input.addEventListener("input", function () { state.q = input.value; state.kind = ""; run(true); });
  chips.forEach(function (c) {
    c.addEventListener("click", function () { state.kind = c.dataset.kind; run(true); });
  });
  moreBtn.addEventListener("click", function () { state.shown += PAGE; render(compute()); });
  app.querySelector(".search-form").addEventListener("submit", function (e) { e.preventDefault(); });

  // Open with ?q=... filled in (from a shared link, or the form's own GET fallback).
  var qm = /[?&]q=([^&]*)/.exec(location.search), tm = /[?&]type=([csra])\b/.exec(location.search);
  if (qm) {
    try { state.q = decodeURIComponent(qm[1].replace(/\+/g, " ")); } catch (e) { state.q = ""; }
    if (tm) state.kind = tm[1];
    input.value = state.q;
    run(true);
  }
  if (!window.matchMedia("(pointer: coarse)").matches) input.focus();
})();
